  1→import { useCallback, useEffect, useState } from 'react';
  2→import { useMfa } from '../../hooks/useMfa';
  3→import { useAuth } from '../../hooks/useAuth';
  4→import { authApi } from '../../lib/api/auth';
  5→import { MfaEnrollmentWizard } from './MfaEnrollmentWizard';
  6→import { AuthorizedDevices } from './AuthorizedDevices';
  7→import { RecoveryPhraseSection } from './RecoveryPhraseSection';
  8→
  9→/**
 10→ * Security tab for the Settings page.
 11→ *
 12→ * Displays MFA status badge, enrollment wizard trigger, authorized devices
 13→ * list, and recovery phrase management. Checks MFA status on mount and
 14→ * after enrollment completes.
 15→ */
 16→export function SecurityTab() {
 17→  const { checkMfaStatus, isMfaEnabled, factorCount, threshold } = useMfa();
 18→  const { logout } = useAuth();
 19→  const [showWizard, setShowWizard] = useState(false);
 20→  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
 21→  const [deleteInput, setDeleteInput] = useState('');
 22→  const [isDeleting, setIsDeleting] = useState(false);
 23→  const [deleteError, setDeleteError] = useState<string | null>(null);
 24→
 25→  // Check MFA status on mount
 26→  useEffect(() => {
 27→    checkMfaStatus();
 28→  }, [checkMfaStatus]);
 29→
 30→  const handleEnrollmentComplete = useCallback(() => {
 31→    setShowWizard(false);
 32→    checkMfaStatus();
 33→  }, [checkMfaStatus]);
 34→
 35→  const handleEnrollmentCancel = useCallback(() => {
 36→    setShowWizard(false);
 37→  }, []);
 38→
 39→  const handleDeleteAccount = useCallback(async () => {
 40→    if (deleteInput !== 'DELETE') return;
 41→    setIsDeleting(true);
 42→    setDeleteError(null);
 43→    try {
 44→      await authApi.deleteAccount();
 45→      // Account deleted server-side. Clear local state and redirect.
 46→      try {
 47→        await logout();
 48→      } catch {
 49→        // Account is already gone — force redirect even if logout cleanup fails
 50→        window.location.href = '/login';
 51→      }
 52→    } catch (err) {
 53→      setDeleteError(err instanceof Error ? err.message : 'Failed to delete account');
 54→    } finally {
 55→      setIsDeleting(false);
 56→    }
 57→  }, [deleteInput, logout]);
 58→
 59→  const handleCancelDelete = useCallback(() => {
 60→    setShowDeleteConfirm(false);
 61→    setDeleteInput('');
 62→    setDeleteError(null);
 63→  }, []);
 64→
 65→  return (
 66→    <div className="security-tab">
 67→      {/* MFA Status Badge */}
 68→      <div className="security-tab-status">
 69→        <span
 70→          className={`security-tab-status-dot ${isMfaEnabled ? 'enabled' : 'disabled'}`}
 71→          aria-hidden="true"
 72→        />
 73→        <span className={`security-tab-status-label ${isMfaEnabled ? 'enabled' : 'disabled'}`}>
 74→          {isMfaEnabled ? '[ENABLED]' : '[DISABLED]'}
 75→        </span>
 76→      </div>
 77→
 78→      {/* Factor info when enabled */}
 79→      {isMfaEnabled && factorCount > 0 && (
 80→        <p className="security-tab-factor-info">
 81→          {factorCount} factors active, {threshold}/{factorCount} threshold
 82→        </p>
 83→      )}
 84→
 85→      {/* Enrollment wizard or trigger */}
 86→      {showWizard ? (
 87→        <MfaEnrollmentWizard
 88→          onComplete={handleEnrollmentComplete}
 89→          onCancel={handleEnrollmentCancel}
 90→        />
 91→      ) : (
 92→        <>
 93→          {/* Enable MFA section (only when disabled) */}
 94→          {!isMfaEnabled && (
 95→            <div className="security-tab-enable">
 96→              <h3 className="security-tab-enable-title">
 97→                {'// enable multi-factor authentication'}
 98→              </h3>
 99→              <p className="security-tab-enable-desc">
100→                Protect your vault with an additional layer of security. New devices will require
101→                approval from an existing device or your recovery phrase.
102→              </p>
103→              <button
104→                type="button"
105→                className="security-tab-enable-btn"
106→                onClick={() => setShowWizard(true)}
107→              >
108→                --enable-mfa
109→              </button>
110→            </div>
111→          )}
112→
113→          {/* Authorized Devices section (only when MFA enabled) */}
114→          {isMfaEnabled && (
115→            <div className="security-tab-section">
116→              <h3 className="security-tab-section-title">{'// authorized devices'}</h3>
117→              <AuthorizedDevices />
118→            </div>
119→          )}
120→
121→          {/* Recovery Phrase section (only when MFA enabled) */}
122→          {isMfaEnabled && (
123→            <div className="security-tab-section">
124→              <h3 className="security-tab-section-title">{'// recovery phrase'}</h3>
125→              <RecoveryPhraseSection />
126→            </div>
127→          )}
128→        </>
129→      )}
130→
131→      {/* Danger Zone */}
132→      <div className="security-tab-danger-zone">
133→        <h3 className="security-tab-danger-zone-title">{'// danger_zone'}</h3>
134→        {!showDeleteConfirm ? (
135→          <div className="security-tab-danger-zone-content">
136→            <p className="security-tab-danger-zone-desc">
137→              permanently delete your account and all associated data. this action cannot be undone.
138→            </p>
139→            <button
140→              type="button"
141→              className="security-tab-danger-btn"
142→              onClick={() => setShowDeleteConfirm(true)}
143→            >
144→              --delete-account
145→            </button>
146→          </div>
147→        ) : (
148→          <div className="security-tab-danger-zone-confirm">
149→            <p className="security-tab-danger-zone-warn">
150→              this will permanently delete your account, vault, files, shares, and all encryption
151→              keys. type <strong>DELETE</strong> to confirm.
152→            </p>
153→            <input
154→              type="text"
155→              className="security-tab-danger-input"
156→              aria-label="Type DELETE to confirm account deletion"
157→              value={deleteInput}
158→              onChange={(e) => setDeleteInput(e.target.value)}
159→              placeholder="type DELETE to confirm"
160→              autoComplete="off"
161→              spellCheck={false}
162→              disabled={isDeleting}
163→            />
164→            {deleteError && <p className="security-tab-danger-error">{deleteError}</p>}
165→            <div className="security-tab-danger-actions">
166→              <button
167→                type="button"
168→                className="security-tab-danger-cancel"
169→                onClick={handleCancelDelete}
170→                disabled={isDeleting}
171→              >
172→                --cancel
173→              </button>
174→              <button
175→                type="button"
176→                className="security-tab-danger-confirm-btn"
177→                onClick={handleDeleteAccount}
178→                disabled={deleteInput !== 'DELETE' || isDeleting}
179→              >
180→                {isDeleting ? 'deleting...' : '--confirm-delete'}
181→              </button>
182→            </div>
183→          </div>
184→        )}
185→      </div>
186→
187→      {/* Desktop note */}
188→      <p className="security-tab-note">
189→        {'// '}MFA is available on web only. Desktop support coming soon.
190→      </p>
191→    </div>
192→  );
193→}
