  1→import { useCallback, useMemo, useState } from 'react';
  2→import { FactorKeyTypeShareDescription } from '@web3auth/mpc-core-kit';
  3→import { useMfa } from '../../hooks/useMfa';
  4→import { RecoveryPhraseGrid } from './RecoveryPhraseGrid';
  5→
  6→/**
  7→ * Recovery phrase status and regeneration section for the Security tab.
  8→ *
  9→ * Shows whether a recovery factor is active, allows regeneration with
 10→ * confirmation, and displays the new phrase with acknowledgment checkbox.
 11→ */
 12→export function RecoveryPhraseSection() {
 13→  const { getFactors, regenerateRecoveryPhrase } = useMfa();
 14→
 15→  const [showConfirm, setShowConfirm] = useState(false);
 16→  const [isRegenerating, setIsRegenerating] = useState(false);
 17→  const [error, setError] = useState<string | null>(null);
 18→  const [newPhrase, setNewPhrase] = useState<string[] | null>(null);
 19→  const [acknowledged, setAcknowledged] = useState(false);
 20→
 21→  const factors = useMemo(() => getFactors(), [getFactors]);
 22→  const hasRecoveryFactor = factors.some(
 23→    (f) => f.type === FactorKeyTypeShareDescription.SeedPhrase || f.type === 'seedPhrase'
 24→  );
 25→
 26→  const handleRegenerate = useCallback(async () => {
 27→    setIsRegenerating(true);
 28→    setError(null);
 29→    try {
 30→      const mnemonic = await regenerateRecoveryPhrase();
 31→      setNewPhrase(mnemonic.split(' '));
 32→      setShowConfirm(false);
 33→    } catch (err) {
 34→      setError(err instanceof Error ? err.message : 'Failed to regenerate recovery phrase');
 35→    } finally {
 36→      setIsRegenerating(false);
 37→    }
 38→  }, [regenerateRecoveryPhrase]);
 39→
 40→  const toggleAcknowledged = useCallback(() => {
 41→    setAcknowledged((prev) => !prev);
 42→  }, []);
 43→
 44→  const handleCheckboxKeyDown = useCallback(
 45→    (e: React.KeyboardEvent) => {
 46→      if (e.key === 'Enter' || e.key === ' ') {
 47→        e.preventDefault();
 48→        toggleAcknowledged();
 49→      }
 50→    },
 51→    [toggleAcknowledged]
 52→  );
 53→
 54→  const handleDismissPhrase = useCallback(() => {
 55→    setNewPhrase(null);
 56→    setAcknowledged(false);
 57→  }, []);
 58→
 59→  return (
 60→    <div className="recovery-section">
 61→      {/* Status */}
 62→      <div className="recovery-section-status">
 63→        <span
 64→          className={`recovery-section-status-dot ${hasRecoveryFactor ? '' : 'inactive'}`}
 65→          aria-hidden="true"
 66→        />
 67→        <span className="recovery-section-status-label">
 68→          {hasRecoveryFactor ? 'recovery phrase active' : 'no recovery phrase'}
 69→        </span>
 70→      </div>
 71→
 72→      {/* Error display */}
 73→      {error && (
 74→        <div className="linked-methods-error" role="alert">
 75→          {error}
 76→          <button
 77→            type="button"
 78→            onClick={() => setError(null)}
 79→            className="linked-methods-error-dismiss"
 80→            aria-label="Dismiss error"
 81→          >
 82→            [x]
 83→          </button>
 84→        </div>
 85→      )}
 86→
 87→      {/* Confirmation dialog for regeneration */}
 88→      {showConfirm && (
 89→        <div className="recovery-section-confirm">
 90→          <p className="recovery-section-confirm-text">
 91→            This will invalidate your current recovery phrase. Any written copies of the old phrase
 92→            will no longer work. Are you sure?
 93→          </p>
 94→          <div className="recovery-section-confirm-actions">
 95→            <button
 96→              type="button"
 97→              className="recovery-section-confirm-btn danger"
 98→              onClick={handleRegenerate}
 99→              disabled={isRegenerating}
100→            >
101→              {isRegenerating ? 'regenerating...' : '--confirm-regenerate'}
102→            </button>
103→            <button
104→              type="button"
105→              className="recovery-section-confirm-btn cancel"
106→              onClick={() => setShowConfirm(false)}
107→              disabled={isRegenerating}
108→            >
109→              --cancel
110→            </button>
111→          </div>
112→        </div>
113→      )}
114→
115→      {/* New phrase display after regeneration */}
116→      {newPhrase && (
117→        <div className="recovery-section-new-phrase">
118→          <h4 className="recovery-section-new-phrase-title">{'// new recovery phrase'}</h4>
119→          <RecoveryPhraseGrid words={newPhrase} />
120→
121→          <div className="mfa-wizard-danger-box" role="alert">
122→            Your previous recovery phrase is now invalid. Write down this new phrase and store it
123→            safely.
124→          </div>
125→
126→          <div
127→            className={`mfa-wizard-checkbox ${acknowledged ? 'checked' : ''}`}
128→            role="checkbox"
129→            aria-checked={acknowledged}
130→            tabIndex={0}
131→            onClick={toggleAcknowledged}
132→            onKeyDown={handleCheckboxKeyDown}
133→          >
134→            <span className="mfa-wizard-checkbox-box" aria-hidden="true">
135→              {acknowledged ? '[x]' : '[ ]'}
136→            </span>
137→            <span className="mfa-wizard-checkbox-label">
138→              I have written down and safely stored my new recovery phrase
139→            </span>
140→          </div>
141→
142→          {acknowledged && (
143→            <button
144→              type="button"
145→              className="recovery-section-btn"
146→              onClick={handleDismissPhrase}
147→              style={{ marginTop: '8px' }}
148→            >
149→              --done
150→            </button>
151→          )}
152→        </div>
153→      )}
154→
155→      {/* Regenerate button (hidden when showing confirm or new phrase) */}
156→      {!showConfirm && !newPhrase && hasRecoveryFactor && (
157→        <div className="recovery-section-actions">
158→          <button
159→            type="button"
160→            className="recovery-section-btn"
161→            onClick={() => setShowConfirm(true)}
162→          >
163→            --regenerate
164→          </button>
165→        </div>
166→      )}
167→    </div>
168→  );
169→}
