 38→ * 2. Resolving an existing registry from IPNS, or creating a new one
 39→ * 3. Adding/updating the current device in the registry
 40→ * 4. Encrypting, pinning to IPFS, and publishing via IPNS
 41→ * 5. Enrolling for TEE auto-republishing when teeKeys are available
 42→ *
 43→ * @returns Registry and IPNS name, or null if any step fails
 44→ */
 45→export async function initializeOrSyncRegistry(params: {
 46→  userPrivateKey: Uint8Array;
 47→  userPublicKey: Uint8Array;
 48→  deviceKeypair: DeviceKeypair;
 49→  deviceInfo: {
 50→    name: string;
 51→    platform: DevicePlatform;
 52→    appVersion: string;
 53→    deviceModel: string;
 54→    ipHash: string;
 55→  };
 56→}): Promise<{ registry: DeviceRegistry; ipnsName: string } | null> {
 57→  try {
 58→    // 1. Derive deterministic IPNS keypair for the registry
 59→    const registryIpns = await deriveRegistryIpnsKeypair(params.userPrivateKey);
 60→
 61→    // 2. Try to resolve existing registry
 62→    let registry: DeviceRegistry | null = null;
 63→    let needsPublish = true;
 64→
 65→    const resolved = await resolveIpnsRecord(registryIpns.ipnsName);
 66→
 67→    if (resolved) {
 68→      // Existing registry found -- fetch and decrypt
 69→      const encryptedBytes = await fetchFromIpfs(resolved.cid);
 70→      registry = await decryptRegistry(encryptedBytes, params.userPrivateKey);
 71→
 72→      // Snapshot before modification for change detection
 73→      const beforeJson = JSON.stringify(registry);
 74→
 75→      // Check if current device already exists
 76→      const existingDevice = registry.devices.find(
 77→        (d) => d.deviceId === params.deviceKeypair.deviceId
 78→      );
 79→
 80→      if (existingDevice) {
 81→        // Update existing device heartbeat and metadata
 82→        existingDevice.lastSeenAt = Date.now();
 83→        existingDevice.appVersion = params.deviceInfo.appVersion;
 84→        existingDevice.deviceModel = params.deviceInfo.deviceModel;
 85→      } else {
 86→        // New device -- register as pending
 87→        const newEntry = createEmptyDeviceEntry({
 88→          deviceKeypair: params.deviceKeypair,
 89→          deviceInfo: params.deviceInfo,
 90→          status: 'pending',
 91→        });
 92→        registry.devices.push(newEntry);
 93→      }
 94→
 95→      // Check if registry actually changed enough to warrant republish
 96→      // Avoid unnecessary republishes when only lastSeenAt changed recently
 97→      // (Pitfall 1 from RESEARCH.md: ECIES nondeterminism means every encrypt = new CID)
 98→      const afterJson = JSON.stringify(registry);
 99→      if (beforeJson === afterJson) {
100→        // Nothing changed at all
101→        needsPublish = false;
102→      } else if (existingDevice) {
103→        // Device existed -- check if only heartbeat fields changed
104→        const beforeParsed = JSON.parse(beforeJson) as DeviceRegistry;
105→        const beforeDevice = beforeParsed.devices.find(
106→          (d) => d.deviceId === params.deviceKeypair.deviceId
107→        );
108→        if (beforeDevice) {
109→          const metadataChanged =
110→            beforeDevice.appVersion !== existingDevice.appVersion ||
111→            beforeDevice.deviceModel !== existingDevice.deviceModel;
112→          if (!metadataChanged) {
113→            // Only lastSeenAt changed -- apply debounce
114→            const timeSinceLastSeen = Date.now() - beforeDevice.lastSeenAt;
115→            if (timeSinceLastSeen < HEARTBEAT_DEBOUNCE_MS) {
116→              needsPublish = false;
117→            }
118→          }
119→        }
120→      }
121→    } else {
122→      // No existing registry -- first device, auto-authorized
123→      registry = {
124→        version: 'v1',
125→        sequenceNumber: 0,
126→        devices: [
127→          createEmptyDeviceEntry({
128→            deviceKeypair: params.deviceKeypair,
129→            deviceInfo: params.deviceInfo,
130→            status: 'authorized',
131→          }),
132→        ],
133→      };
134→    }
135→
136→    if (!needsPublish) {
137→      return { registry, ipnsName: registryIpns.ipnsName };
138→    }
139→
140→    // 5. Increment sequence number
141→    registry.sequenceNumber++;
142→
143→    // 6. Encrypt registry with user's public key
144→    const encryptedBytes = await encryptRegistry(registry, params.userPublicKey);
145→
146→    // 7. Pin to IPFS (cast to BlobPart; never use .buffer per CLAUDE.md)
147→    const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
148→
149→    // 8. Publish IPNS with TEE enrollment
150→    const teeKeys = useAuthStore.getState().teeKeys;
151→    let encryptedIpnsKey: string | undefined;
152→    let keyEpoch: number | undefined;
153→
154→    if (teeKeys?.currentPublicKey) {
155→      // ECIES-wrap the registry IPNS private key with TEE public key
156→      const wrappedKey = await wrapKey(
157→        registryIpns.privateKey,
158→        hexToBytes(teeKeys.currentPublicKey)
159→      );
160→      encryptedIpnsKey = bytesToHex(wrappedKey);
161→      keyEpoch = teeKeys.currentEpoch;
162→    }
163→
164→    await createAndPublishIpnsRecord({
165→      ipnsPrivateKey: registryIpns.privateKey,
166→      ipnsName: registryIpns.ipnsName,
167→      metadataCid: cid,
168→      sequenceNumber: BigInt(registry.sequenceNumber),
169→      encryptedIpnsPrivateKey: encryptedIpnsKey,
170→      keyEpoch,
171→    });
172→
173→    return { registry, ipnsName: registryIpns.ipnsName };
174→  } catch (error) {
175→    // Registry failures must NEVER block login
176→    console.error('[DeviceRegistry] Failed to sync registry:', error);
177→    return null;
178→  }
179→}
180→
181→/**
182→ * Load the registry from IPNS (read-only).
183→ *
184→ * Used by the polling hook (Plan 03) to check for remote changes.
185→ * Does NOT modify the registry -- just resolves, fetches, and decrypts.
186→ *
187→ * @returns Registry data with IPNS name and sequence number, or null on failure
188→ */
189→export async function loadRegistry(userPrivateKey: Uint8Array): Promise<{
190→  registry: DeviceRegistry;
191→  ipnsName: string;
192→  sequenceNumber: bigint;
193→} | null> {
194→  try {
195→    const registryIpns = await deriveRegistryIpnsKeypair(userPrivateKey);
196→    const resolved = await resolveIpnsRecord(registryIpns.ipnsName);
197→
198→    if (!resolved) {
199→      return null;
200→    }
201→
202→    const encryptedBytes = await fetchFromIpfs(resolved.cid);
203→    const registry = await decryptRegistry(encryptedBytes, userPrivateKey);
204→
205→    return {
206→      registry,
207→      ipnsName: registryIpns.ipnsName,
208→      sequenceNumber: resolved.sequenceNumber,
209→    };
210→  } catch (error) {
211→    console.error('[DeviceRegistry] Failed to load registry:', error);
212→    return null;
213→  }
214→}
