  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useVaultStore } from '../stores/vault.store';
  9→import { useFolderStore } from '../stores/folder.store';
 10→import { useSyncStore } from '../stores/sync.store';
 11→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 12→import { useMfaStore } from '../stores/mfa.store';
 13→import {
 14→  initializeVault,
 15→  encryptVaultKeys,
 16→  decryptVaultKeys,
 17→  deriveIpnsName,
 18→  hexToBytes,
 19→  bytesToHex,
 20→} from '@cipherbox/crypto';
 21→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 22→import { detectDeviceInfo } from '../lib/device/info';
 23→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 24→import { clearFileSizeCache } from './useFileSize';
 25→
 26→export function useAuth() {
 27→  const navigate = useNavigate();
 28→  const {
 29→    isLoggedIn: coreKitLoggedIn,
 30→    isInitialized: coreKitInitialized,
 31→    isRequiredShare,
 32→    loginWithGoogle: coreKitLoginGoogle,
 33→    loginWithEmailOtp: coreKitLoginEmail,
 34→    loginWithWallet: coreKitLoginWallet,
 35→    getVaultKeypair,
 36→    getPublicKeyHex,
 37→    logout: coreKitLogout,
 38→  } = useCoreKitAuth();
 39→  const { syncStatus } = useCoreKit();
 40→  const {
 41→    accessToken,
 42→    isAuthenticated,
 43→    lastAuthMethod,
 44→    userEmail,
 45→    setAccessToken,
 46→    setLastAuthMethod,
 47→    setUserEmail,
 48→    setVaultKeypair,
 49→    logout: clearAuthState,
 50→  } = useAuthStore();
 51→
 52→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 53→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 54→  const restoringRef = useRef(false);
 55→
 56→  // Stable refs for functions used in the session restoration effect.
 57→  // This prevents the effect from re-firing when function references change.
 58→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 59→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 60→
 61→  // Pending auth state for REQUIRED_SHARE flow
 62→  // Stored so completeRequiredShare() can resume after factor input
 63→  const [pendingCipherboxJwt, setPendingCipherboxJwt] = useState<string | null>(null);
 64→  const [pendingAuthMethod, setPendingAuthMethod] = useState<string | null>(null);
 65→
 66→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 67→
 68→  // Get vault store actions
 69→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 70→
 71→  /**
 72→   * Initialize vault for new users or load existing vault keys.
 73→   * Called after successful backend authentication.
 74→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 75→   */
 76→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 77→    // Get user's secp256k1 keypair from Core Kit TSS export
 78→    const userKeypair = await getVaultKeypair();
 79→
 80→    if (!userKeypair) {
 81→      throw new Error('Failed to get vault keypair from Core Kit');
 82→    }
 83→
 84→    // Store keypair in auth store for crypto operations
 85→    setVaultKeypair(userKeypair);
 86→
 87→    try {
 88→      // Try to fetch existing vault
 89→      const existingVault = await vaultApi.getVault();
 90→
 91→      // Store TEE keys if available
 92→      if (existingVault.teeKeys) {
 93→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 94→      }
 95→
 96→      // Vault exists - decrypt keys and load into store
 97→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 98→      const decryptedVault = await decryptVaultKeys(
 99→        {
100→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
101→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
102→        },
103→        userKeypair.privateKey
104→      );
105→
106→      setVaultKeys({
107→        rootFolderKey: decryptedVault.rootFolderKey,
108→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
109→        rootIpnsName: existingVault.rootIpnsName,
110→        vaultId: existingVault.id,
111→      });
112→    } catch (error) {
113→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
114→
115→      if (is404) {
116→        // New user - initialize vault
117→        console.log(
118→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
119→        );
120→        const newVault = await initializeVault(userKeypair.privateKey);
121→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
122→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
123→
124→        const storedVault = await vaultApi.initVault({
125→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
126→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
127→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
128→          rootIpnsName,
129→        });
130→
131→        if (storedVault.teeKeys) {
132→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
133→        }
134→
135→        setVaultKeys({
136→          rootFolderKey: newVault.rootFolderKey,
137→          rootIpnsKeypair: newVault.rootIpnsKeypair,
138→          rootIpnsName,
139→          vaultId: storedVault.id,
140→          isNewVault: true,
141→        });
142→      } else {
143→        console.error('[useAuth] Failed to load vault:', error);
144→        throw error;
145→      }
146→    }
147→
148→    // Non-blocking device registry initialization (fire-and-forget)
149→    // Placed after vault load so registry failures never block login
150→    void (async () => {
151→      try {
152→        const deviceKeypair = await getOrCreateDeviceIdentity();
153→        const deviceInfo = detectDeviceInfo();
154→        const result = await initializeOrSyncRegistry({
155→          userPrivateKey: userKeypair.privateKey,
156→          userPublicKey: userKeypair.publicKey,
157→          deviceKeypair,
158→          deviceInfo: { ...deviceInfo, ipHash: '' },
159→        });
160→        if (result) {
161→          useDeviceRegistryStore
162→            .getState()
163→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
164→        }
165→      } catch (error) {
166→        console.error('[Auth] Device registry init failed (non-blocking):', error);
167→      }
168→    })();
169→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
170→
171→  /**
172→   * Complete backend authentication after Core Kit login.
173→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
174→   * to the backend with loginType 'corekit'. The backend verifies it against
175→   * its own JWKS since CipherBox is the identity provider.
176→   */
177→  const completeBackendAuth = useCallback(
178→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
179→      // 1. Get real publicKey from Core Kit TSS export
180→      const publicKey = await getPublicKeyHex();
181→      if (!publicKey) {
182→        throw new Error('Failed to get publicKey from Core Kit');
183→      }
184→
185→      // publicKey available for debugging via DevTools if needed
186→
187→      // 2. Authenticate with CipherBox backend
188→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
189→      const response = await authApi.login({
190→        idToken: cipherboxJwt,
191→        publicKey,
192→        loginType: 'corekit',
193→      });
194→
195→      // 3. Store access token (refresh token in HTTP-only cookie)
196→      setAccessToken(response.accessToken);
197→
198→      // 4. Remember auth method for UX
199→      setLastAuthMethod(authMethod);
200→
201→      // 5. Initialize or load vault
202→      await initializeOrLoadVault();
203→    },
204→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
205→  );
206→
207→  /**
208→   * Complete the login flow after REQUIRED_SHARE is resolved.
209→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
210→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
211→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
212→   */
213→  const completeRequiredShare = useCallback(async (): Promise<void> => {
214→    const jwt = pendingCipherboxJwt;
215→    const method = pendingAuthMethod;
216→
217→    if (!jwt || !method) {
218→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
219→    }
220→
221→    // Core Kit should now be LOGGED_IN after inputFactorKey()
222→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
223→    await completeBackendAuth(method, jwt);
224→
225→    // NOW sync Core Kit React state to LOGGED_IN.
226→    // We deliberately delayed this from inputFactorKey() to prevent the session
227→    // restoration effect from firing before backend auth completed.
228→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
229→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
230→    syncStatus();
231→
232→    // Clear pending state
233→    setPendingCipherboxJwt(null);
234→    setPendingAuthMethod(null);
235→
236→    // Navigate to files
237→    navigate('/files');
238→  }, [pendingCipherboxJwt, pendingAuthMethod, completeBackendAuth, syncStatus, navigate]);
239→
240→  /**
241→   * Login with Google OAuth token.
242→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
243→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
244→   */
245→  const loginWithGoogle = useCallback(
246→    async (googleIdToken: string): Promise<void> => {
247→      if (isLoggingIn) return;
248→      setIsLoggingIn(true);
249→      try {
250→        // 1. Core Kit login via CipherBox identity provider
251→        const {
252→          cipherboxJwt,
253→          email,
254→          userId,
255→          status: coreKitStatus,
256→        } = await coreKitLoginGoogle(googleIdToken);
257→
258→        if (coreKitStatus === 'required_share') {
259→          // MFA enabled but device factor missing.
